import{_ as d,c as e,o as t,b2 as c}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"定时任务设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-16-job-design.md","filePath":"superpowers/specs/2026-05-16-job-design.md"}'),r={name:"superpowers/specs/2026-05-16-job-design.md"};function a(i,o,n,l,s,b){return t(),e("div",null,[...o[0]||(o[0]=[c('<h1 id="定时任务设计文档" tabindex="-1">定时任务设计文档 <a class="header-anchor vp-link" href="#定时任务设计文档" aria-label="Permalink to &quot;定时任务设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在 <code>quickboot</code> + <code>quick-ui</code> 中实现《定时任务需求文档》所述能力：管理调度任务与执行日志，支持任务增删改查、状态切换、立即执行、Cron 表达式生成器回填、日志审计与导出。</p><ul><li><strong>调度引擎</strong>：Quartz + <strong>JDBC JobStore</strong> + <strong>集群</strong>（<code>QRTZ_</code> 表前缀）。</li><li><strong>执行模型</strong>：<code>invoke_target</code> 为 Spring <strong>Bean 名称</strong>；目标 Bean 须实现 <strong><code>ITask.execute(String params)</code></strong>（延续 <code>原始需求/old/quick-boot</code>，非若依反射串）。</li><li><strong>路径与权限</strong>以需求文档为真源：<code>/monitor/job*</code>、<code>/monitor/jobLog*</code>；<code>monitor:job:*</code> 及日志侧 <code>monitor:job:query|remove|export</code>。</li></ul><h2 id="_2-已确认决策摘要" tabindex="-1">2. 已确认决策摘要 <a class="header-anchor vp-link" href="#_2-已确认决策摘要" aria-label="Permalink to &quot;2. 已确认决策摘要&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>调用目标</td><td>Bean 名 + <code>ITask</code>；保存/修改时校验 Bean 存在且类型正确</td></tr><tr><td>任务参数</td><td>独立表字段 <strong><code>params</code></strong>（扩展列，与若依核心列并存）</td></tr><tr><td>Quartz</td><td>JDBC <code>LocalDataSourceJobStore</code>，<code>isClustered=true</code>，<code>tablePrefix=QRTZ_</code></td></tr><tr><td>表/字典</td><td>对齐若依 <code>sys_job</code> / <code>sys_job_log</code> 语义；主键 <code>job_id</code> / <code>job_log_id</code></td></tr><tr><td>HTTP 动词</td><td>与 <code>logininfor</code> / <code>operlog</code> 一致：列表/详情 <strong>GET</strong>；改删/改状态/执行/导出/清空 <strong>POST</strong>（与需求字面 <code>PUT/DELETE</code> 不一致，以本设计为准）</td></tr><tr><td>并发策略</td><td><code>concurrent</code>：<strong><code>0</code> 允许</strong> / <strong><code>1</code> 禁止</strong>（修正旧栈 <code>&quot;Y&quot;</code> 误判）</td></tr><tr><td>错失策略</td><td><code>misfire_policy</code>：<code>0</code> 默认 / <code>1</code> 立即 / <code>2</code> 一次 / <code>3</code> 放弃</td></tr><tr><td>任务状态</td><td><code>status</code>：<code>0</code> 正常 / <code>1</code> 暂停；<strong>新增默认暂停</strong>（<code>1</code>），注册前须显式启用</td></tr><tr><td>Cron UI</td><td>引入 Vue3 兼容 Cron 组件（如 vcrontab 类库）弹窗回填</td></tr><tr><td>日志页</td><td>独立路由 <code>/monitor/job-log</code>，支持 query 预填 <code>jobName</code> / <code>jobGroup</code></td></tr><tr><td>写日志失败</td><td>不得影响 Quartz 调度线程外的业务；写库异常仅记录 error 日志</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-范围" tabindex="-1">3.1 范围 <a class="header-anchor vp-link" href="#_3-1-范围" aria-label="Permalink to &quot;3.1 范围&quot;">​</a></h3><ul><li>Flyway：<code>sys_job</code>、<code>sys_job_log</code>、<code>QRTZ_*</code> 建表、字典种子、菜单与管理员角色授权（建议单文件如 <code>V19__sys_job.sql</code>，序号以实现时仓库最新迁移为准）。</li><li>后端：<code>io.github.genkidoudou.web.monitor.job</code> 包；Quartz <code>ScheduleConfig</code>、<code>ScheduleUtils</code>、<code>AbstractQuartzJob</code>、<code>ITask</code>、启动加载 <code>CommandLineRunner</code>；可选示例 Bean <code>qcDemoTask</code>。</li><li>前端：任务列表/表单、日志列表/详情、API、菜单权限、Cron 生成器。</li></ul><h3 id="_3-2-非范围-本期不做" tabindex="-1">3.2 非范围（本期不做） <a class="header-anchor vp-link" href="#_3-2-非范围-本期不做" aria-label="Permalink to &quot;3.2 非范围（本期不做）&quot;">​</a></h3><ul><li>若依式 <code>bean.method(&#39;arg&#39;)</code> 反射调用与白名单解析。</li><li>远程/RMI/HTTP 调度、多租户调度隔离、日志异步批量落库。</li><li>替代全局链路追踪或操作日志采集机制。</li></ul><h2 id="_4-数据模型" tabindex="-1">4. 数据模型 <a class="header-anchor vp-link" href="#_4-数据模型" aria-label="Permalink to &quot;4. 数据模型&quot;">​</a></h2><h3 id="_4-1-sys-job" tabindex="-1">4.1 <code>sys_job</code> <a class="header-anchor vp-link" href="#_4-1-sys-job" aria-label="Permalink to &quot;4.1 `sys_job`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>job_id</code></td><td>主键（BIGINT，与项目现有分配策略一致）</td></tr><tr><td><code>job_name</code></td><td>任务名称</td></tr><tr><td><code>job_group</code></td><td>任务组名（字典 <code>sys_job_group</code>）</td></tr><tr><td><code>invoke_target</code></td><td>调用目标字符串（<strong>Spring Bean 名</strong>）</td></tr><tr><td><code>cron_expression</code></td><td>Cron 表达式</td></tr><tr><td><code>misfire_policy</code></td><td>错失执行策略（字典 <code>sys_job_misfire_policy</code>）</td></tr><tr><td><code>concurrent</code></td><td>是否并发：<code>0</code> 允许 / <code>1</code> 禁止</td></tr><tr><td><code>status</code></td><td><code>0</code> 正常 / <code>1</code> 暂停（字典 <code>sys_job_status</code>）</td></tr><tr><td><code>params</code></td><td><strong>项目扩展</strong>：执行参数，可空</td></tr><tr><td><code>create_by</code> / <code>create_time</code> / <code>update_by</code> / <code>update_time</code> / <code>remark</code></td><td>审计字段</td></tr></tbody></table></div><p>建议索引：<code>job_name</code>、<code>job_group</code>、<code>status</code>。</p><h3 id="_4-2-sys-job-log" tabindex="-1">4.2 <code>sys_job_log</code> <a class="header-anchor vp-link" href="#_4-2-sys-job-log" aria-label="Permalink to &quot;4.2 `sys_job_log`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>job_log_id</code></td><td>主键</td></tr><tr><td><code>job_id</code></td><td>关联任务 ID（任务删除后仍保留日志，可空）</td></tr><tr><td><code>job_name</code> / <code>job_group</code> / <code>invoke_target</code></td><td>执行快照</td></tr><tr><td><code>job_message</code></td><td>日志信息（成功简述；失败可为固定文案）</td></tr><tr><td><code>status</code></td><td><code>0</code> 成功 / <code>1</code> 失败（复用 <code>sys_common_status</code>）</td></tr><tr><td><code>exception_info</code></td><td>异常信息（截断上限 <strong>2000</strong> 字符）</td></tr><tr><td><code>create_time</code></td><td>执行时间（列表「执行时间」列）</td></tr></tbody></table></div><p>可选扩展列：<code>params</code> 快照，便于审计（实现计划可选）。</p><h3 id="_4-3-quartz-表-qrtz" tabindex="-1">4.3 Quartz 表（<code>QRTZ_</code>） <a class="header-anchor vp-link" href="#_4-3-quartz-表-qrtz" aria-label="Permalink to &quot;4.3 Quartz 表（`QRTZ_`）&quot;">​</a></h3><ul><li>Flyway 引入 Quartz 官方 JDBC 建表脚本（MySQL 方言），与 <code>ScheduleConfig</code> 中 <code>tablePrefix=QRTZ_</code> 一致。</li><li>集群：<code>org.quartz.jobStore.isClustered=true</code>，<code>instanceId=AUTO</code>，<code>clusterCheckinInterval=15000</code>。</li></ul><h3 id="_4-4-字典与菜单" tabindex="-1">4.4 字典与菜单 <a class="header-anchor vp-link" href="#_4-4-字典与菜单" aria-label="Permalink to &quot;4.4 字典与菜单&quot;">​</a></h3><p><strong>字典类型（示例）</strong></p><div class="vp-table"><table><thead><tr><th>dict_type</th><th>用途</th></tr></thead><tbody><tr><td><code>sys_job_group</code></td><td>任务组（DEFAULT 等）</td></tr><tr><td><code>sys_job_status</code></td><td>任务状态 正常/暂停</td></tr><tr><td><code>sys_job_misfire_policy</code></td><td>错失策略</td></tr><tr><td><code>sys_common_status</code></td><td>日志执行成功/失败（复用）</td></tr></tbody></table></div><p><strong>菜单（挂载监控父菜单 <code>parent_id=2000</code>，<code>menu_id</code> 与 V16/V17/V18 错开）</strong></p><ul><li>目录/菜单「定时任务」：<code>path=job</code>，<code>component=monitor/job/index</code>，<code>perms=monitor:job:list</code>。</li><li>按钮：<code>add</code> / <code>edit</code> / <code>remove</code> / <code>export</code> / <code>query</code> / <code>changeStatus</code>（与需求一致）。</li><li>「调度日志」：<code>path=job-log</code>，<code>component=monitor/job-log/index</code>，列表权限 <code>monitor:job:query</code>；按钮 <code>remove</code>、<code>export</code>。</li><li>超级管理员 <code>role_id=1</code> 授权上述菜单。</li></ul><h2 id="_5-调度与执行" tabindex="-1">5. 调度与执行 <a class="header-anchor vp-link" href="#_5-调度与执行" aria-label="Permalink to &quot;5. 调度与执行&quot;">​</a></h2><h3 id="_5-1-组件职责" tabindex="-1">5.1 组件职责 <a class="header-anchor vp-link" href="#_5-1-组件职责" aria-label="Permalink to &quot;5.1 组件职责&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>组件</th><th>职责</th></tr></thead><tbody><tr><td><code>ScheduleConfig</code></td><td>注册 <code>SchedulerFactoryBean</code>、数据源 JobStore、集群与线程池参数</td></tr><tr><td><code>ScheduleUtils</code></td><td>创建/更新/暂停/删除 Job；按 <code>concurrent</code> 选择 Job 实现类</td></tr><tr><td><code>QuartzJobExecution</code></td><td>允许并发执行</td></tr><tr><td><code>QuartzDisallowConcurrentExecution</code></td><td>禁止并发（<code>@DisallowConcurrentExecution</code>）</td></tr><tr><td><code>AbstractQuartzJob</code></td><td>统一 before/after、写 <code>sys_job_log</code></td></tr><tr><td><code>JobScheduleRunner</code></td><td>应用启动后加载 <code>status=0</code> 的任务到 Scheduler</td></tr><tr><td><code>ITask</code></td><td><code>void execute(String params)</code> 业务契约</td></tr></tbody></table></div><h3 id="_5-2-执行流程" tabindex="-1">5.2 执行流程 <a class="header-anchor vp-link" href="#_5-2-执行流程" aria-label="Permalink to &quot;5.2 执行流程&quot;">​</a></h3><ol><li>Quartz 触发 → <code>AbstractQuartzJob.execute</code>。</li><li>从 <code>JobDataMap</code> 还原任务快照（含 <code>params</code>）。</li><li><code>ApplicationContext.getBean(invokeTarget)</code> → 强转 <code>ITask</code> → <code>execute(params)</code>。</li><li><code>after</code>：写 <code>sys_job_log</code>（成功 <code>status=0</code>；异常 <code>status=1</code> + <code>exception_info</code>）。</li><li>写库 <code>try/catch</code>：失败仅打日志，不向 Quartz 抛业务异常。</li></ol><h3 id="_5-3-任务生命周期" tabindex="-1">5.3 任务生命周期 <a class="header-anchor vp-link" href="#_5-3-任务生命周期" aria-label="Permalink to &quot;5.3 任务生命周期&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>操作</th><th>行为</th></tr></thead><tbody><tr><td>新增</td><td>校验 Cron、Bean/<code>ITask</code>；默认 <code>status=1</code>；落库后 <strong>不</strong> 自动注册（或注册为暂停，与若依一致）</td></tr><tr><td>修改</td><td>校验通过后更新库表；若原任务已注册则 <code>updateScheduleJob</code></td></tr><tr><td>删除</td><td>先 <code>scheduler.deleteJob</code>，再删库表；支持批量</td></tr><tr><td>改状态</td><td><code>0</code>→恢复调度 / <code>1</code>→暂停；库表与 Scheduler 同步</td></tr><tr><td>立即执行</td><td><code>triggerJob(jobKey, dataMap)</code>；仍写调度日志</td></tr></tbody></table></div><h3 id="_5-4-校验规则" tabindex="-1">5.4 校验规则 <a class="header-anchor vp-link" href="#_5-4-校验规则" aria-label="Permalink to &quot;5.4 校验规则&quot;">​</a></h3><ul><li><code>CronUtils.isValid(cronExpression)</code>（基于 <code>org.quartz.CronExpression</code>）。</li><li><code>invoke_target</code> 非空；Bean 必须存在且 <code>instanceof ITask</code>。</li><li>禁止将非 <code>ITask</code> 的通用 Service 作为目标（防止误调用）。</li></ul><h3 id="_5-5-示例任务" tabindex="-1">5.5 示例任务 <a class="header-anchor vp-link" href="#_5-5-示例任务" aria-label="Permalink to &quot;5.5 示例任务&quot;">​</a></h3><ul><li><code>@Component(&quot;qcDemoTask&quot;)</code> 实现 <code>ITask</code>，<code>execute</code> 内打 info 日志。</li><li>Flyway <strong>可选</strong>插入一条演示任务（默认暂停），便于联调；生产环境可仅保留 Bean 文档说明。</li></ul><h2 id="_6-后端接口契约" tabindex="-1">6. 后端接口契约 <a class="header-anchor vp-link" href="#_6-后端接口契约" aria-label="Permalink to &quot;6. 后端接口契约&quot;">​</a></h2><p>包路径：<code>io.github.genkidoudou.web.monitor.job</code>（任务）、<code>...joblog</code> 或同包 <code>log</code> 子包（日志），实现阶段二选一保持清晰。</p><p>注解：<code>@Tag</code>、<code>@Operation</code>、<code>@Parameter</code>、<code>@SaCheckPermission</code>；Jakarta Validation；业务失败使用 <code>WarningException</code> 等，<strong>禁止</strong> <code>IllegalArgumentException</code> 作为业务信号。</p><p>依赖：<code>quickboot-web</code> 增加 <code>spring-boot-starter-quartz</code>。</p><h3 id="_6-1-任务-monitor-job" tabindex="-1">6.1 任务 <code>/monitor/job</code> <a class="header-anchor vp-link" href="#_6-1-任务-monitor-job" aria-label="Permalink to &quot;6.1 任务 `/monitor/job`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/list</code></td><td><code>monitor:job:list</code></td><td>分页；条件：任务名称、组名、状态</td></tr><tr><td>GET</td><td><code>/{jobId}</code></td><td><code>monitor:job:query</code></td><td>详情</td></tr><tr><td>POST</td><td><code>/</code></td><td><code>monitor:job:add</code></td><td>新增</td></tr><tr><td>POST</td><td><code>/edit</code></td><td><code>monitor:job:edit</code></td><td>修改</td></tr><tr><td>POST</td><td><code>/remove</code></td><td><code>monitor:job:remove</code></td><td>body：<code>jobIds</code>（<code>Long[]</code>）</td></tr><tr><td>POST</td><td><code>/changeStatus</code></td><td><code>monitor:job:changeStatus</code></td><td>body：<code>jobId</code>、<code>status</code></td></tr><tr><td>POST</td><td><code>/run</code></td><td><code>monitor:job:changeStatus</code></td><td>body：<code>jobId</code>；返回明确成功文案（满足「立即执行成功反馈」）</td></tr><tr><td>POST</td><td><code>/export</code></td><td><code>monitor:job:export</code></td><td>Excel；筛选与列表一致；行数上限默认 <strong>10000</strong></td></tr></tbody></table></div><h3 id="_6-2-日志-monitor-joblog" tabindex="-1">6.2 日志 <code>/monitor/jobLog</code> <a class="header-anchor vp-link" href="#_6-2-日志-monitor-joblog" aria-label="Permalink to &quot;6.2 日志 `/monitor/jobLog`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/list</code></td><td><code>monitor:job:query</code></td><td>分页；任务名、组名、状态、执行时间区间</td></tr><tr><td>GET</td><td><code>/{jobLogId}</code></td><td><code>monitor:job:query</code></td><td>详情</td></tr><tr><td>POST</td><td><code>/remove</code></td><td><code>monitor:job:remove</code></td><td>body：<code>jobLogIds</code></td></tr><tr><td>POST</td><td><code>/clean</code></td><td><code>monitor:job:remove</code></td><td>清空</td></tr><tr><td>POST</td><td><code>/export</code></td><td><code>monitor:job:export</code></td><td>导出</td></tr></tbody></table></div><p><strong>说明</strong>：需求文档日志路径写作 <code>jobLog</code>（驼峰），与若依 <code>/monitor/jobLog</code> 一致；前端 API 模块与之对齐。</p><h2 id="_7-前端-quick-ui" tabindex="-1">7. 前端（<code>quick-ui</code>） <a class="header-anchor vp-link" href="#_7-前端-quick-ui" aria-label="Permalink to &quot;7. 前端（`quick-ui`）&quot;">​</a></h2><p>实现前须阅读 <code>DESIGN.md</code>、<code>sdd/前端代码规范.md</code>（见 <code>AGENTS.md</code>）。</p><h3 id="_7-1-任务页-views-monitor-job-index-vue" tabindex="-1">7.1 任务页 <code>views/monitor/job/index.vue</code> <a class="header-anchor vp-link" href="#_7-1-任务页-views-monitor-job-index-vue" aria-label="Permalink to &quot;7.1 任务页 `views/monitor/job/index.vue`&quot;">​</a></h3><ul><li><code>C7JsonTable</code>：查询（任务名称、组名、状态）；列（编号、名称、组、cron、调用目标、状态）。</li><li>工具栏：新增、修改、删除、导出；跳转「调度日志」。</li><li>行操作：详情、修改、删除、<strong>立即执行</strong>、<strong>查看日志</strong>（带 <code>jobName</code>、<code>jobGroup</code> query）。</li><li>状态列：<code>el-switch</code>，<code>active-value=&quot;0&quot;</code>、<code>inactive-value=&quot;1&quot;</code>；<code>changeStatus</code> 失败时 <strong>回滚</strong> switch（验收硬要求）。</li><li>表单弹窗：必填 <code>jobName</code>、<code>invokeTarget</code>、<code>cronExpression</code>；<code>jobGroup</code>、<code>misfirePolicy</code>、<code>concurrent</code>、<code>status</code>、<code>params</code>、<code>remark</code>；<code>invokeTarget</code> 旁 tooltip 说明须为 <code>ITask</code> Bean 名。</li></ul><h3 id="_7-2-cron-生成器" tabindex="-1">7.2 Cron 生成器 <a class="header-anchor vp-link" href="#_7-2-cron-生成器" aria-label="Permalink to &quot;7.2 Cron 生成器&quot;">​</a></h3><ul><li>依赖 Vue3 + Element Plus 兼容的 Cron 组件（实现阶段选定具体包，如 <code>@vcrontab/vue3</code> 或社区等价物）。</li><li>弹窗选择后回填 <code>cronExpression</code>；关闭不污染原值。</li></ul><h3 id="_7-3-日志页-views-monitor-job-log-index-vue" tabindex="-1">7.3 日志页 <code>views/monitor/job-log/index.vue</code> <a class="header-anchor vp-link" href="#_7-3-日志页-views-monitor-job-log-index-vue" aria-label="Permalink to &quot;7.3 日志页 `views/monitor/job-log/index.vue`&quot;">​</a></h3><ul><li>独立路由；<code>onMounted</code> 读取 <code>route.query.jobName</code>、<code>jobGroup</code> 作为默认筛选。</li><li>列：日志编号、任务名称、组、调用目标、日志信息、执行状态、执行时间。</li><li>操作：详情、删除、清空、导出、返回任务页。</li></ul><h3 id="_7-4-api-与权限" tabindex="-1">7.4 API 与权限 <a class="header-anchor vp-link" href="#_7-4-api-与权限" aria-label="Permalink to &quot;7.4 API 与权限&quot;">​</a></h3><ul><li><code>api/monitor/job.js</code>、<code>api/monitor/jobLog.js</code>。</li><li><code>v-hasPermi</code> 与菜单 <code>perms</code> 一致。</li></ul><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>验收项（需求）</th><th>验证方式</th></tr></thead><tbody><tr><td>状态切换失败回滚开关</td><td>模拟 <code>changeStatus</code> 失败，断言 switch 恢复原值</td></tr><tr><td>立即执行成功反馈</td><td><code>POST /run</code> 成功 + 前端 <code>ElMessage.success</code></td></tr><tr><td>任务页进日志带筛选</td><td>跳转 query 生效且列表首查命中</td></tr><tr><td>Cron 非法</td><td>前后端拒绝保存</td></tr><tr><td>调度写日志</td><td>Cron 触发与立即执行均产生 <code>sys_job_log</code> 记录</td></tr><tr><td>Bean 校验</td><td>非 <code>ITask</code> Bean 保存失败并提示</td></tr></tbody></table></div><p>建议联调顺序：Flyway → 启动无报错 → 新增 demo 任务 → 启用 → 立即执行 → 查日志 → 导出。</p><h2 id="_9-后续步骤" tabindex="-1">9. 后续步骤 <a class="header-anchor vp-link" href="#_9-后续步骤" aria-label="Permalink to &quot;9. 后续步骤&quot;">​</a></h2><p>在单独会话中按 <strong>writing-plans</strong> 产出 <code>docs/superpowers/plans/2026-05-16-job.md</code> 的实现任务清单后再编码。可选同步创建 OpenSpec change（如 <code>add-monitor-job</code>）供 <code>/opsx:apply</code> 跟踪。</p><hr><p><strong>文档版本</strong>：2026-05-16<br><strong>关联需求</strong>：<code>原始需求/系统管理/定时任务-需求文档.md</code><br><strong>关联设计</strong>：<code>docs/superpowers/specs/2026-05-16-logininfor-design.md</code>（监控模块与 POST 约定）、<code>docs/superpowers/specs/2026-05-16-operlog-design.md</code>（列表/导出风格）<br><strong>参考实现</strong>：<code>原始需求/old/quick-boot/quick-boot-system/.../quartz/</code>（<code>ScheduleConfig</code>、<code>AbstractQuartzJob</code>、<code>ITask</code>）</p>',62)])])}const p=d(r,[["render",a]]);export{h as __pageData,p as default};
